        // Contador de tempo de sessão
        let sessionStartTime = Date.now() - (25 * 60 * 1000 + 13 * 1000); // Simula 25min 13seg já decorridos
        
        function updateSessionTimer() {
            const elapsed = Date.now() - sessionStartTime;
            const minutes = Math.floor(elapsed / 60000);
            const seconds = Math.floor((elapsed % 60000) / 1000);
            const formatted = `${minutes}:${seconds.toString().padStart(2, '0')}`;
            
            document.querySelectorAll('.session-timer').forEach(el => {
                el.textContent = formatted;
            });
        }
        
        // Atualiza a cada segundo
        setInterval(updateSessionTimer, 1000);
        updateSessionTimer();
        
        // Aplica variante selecionada NA BARRA REAL
        function applyVariant() {
            const variantSelector = document.getElementById('variant-selector');
            const buttonStyleSelector = document.getElementById('button-style-selector');
            const contentVariant = variantSelector.value;
            const buttonStyle = buttonStyleSelector.value; // Sempre usa o valor atualmente selecionado
            
            if (!contentVariant) {
                alert('Por favor, selecione uma variante de conteúdo primeiro!');
                return;
            }
            
            const statusBar = document.getElementById('session-status-bar');
            
            if (!statusBar) {
                alert('Barra de status não encontrada! Verifique se o arquivo session-status-bar.php foi incluído corretamente.');
                return;
            }
            
            // Busca ou cria o container - ele pode não existir se renderVariantContent() ainda não foi chamada
            let container = document.getElementById('session-status-container');
            if (!container) {
                // Container será criado pelas funções de variantes abaixo
                debugLog('📦 Container não existe ainda, será criado pela variante');
            }
            
            // Salva no localStorage para persistência (separado)
            localStorage.setItem('content_variant', contentVariant);
            localStorage.setItem('button_style', buttonStyle);
            
            // Mostra a barra se estiver oculta
            if (window.sessionStatusBarAPI) {
                window.sessionStatusBarAPI.show();
            }
            
            // Dados de exemplo para demonstração
            const userData = {
                name: 'João Silva',
                superuser_level: 9,
                photoUrl: 'https://fastly.4sqi.net/img/user/260x260/1590360_ZYrr0ze4_BcykHoOxHkpoKkawwD9Guq9qPz1r7sl430Bynv972LxW1LvN_QXB8Cij6OyQwCiZ.jpg'
            };
            
            // Aplica o estilo baseado na variante E estilo de botão
            applyVariantStyles(contentVariant, buttonStyle, container, userData);
            
            // Feedback visual
            const variantName = variantSelector.options[variantSelector.selectedIndex].text;
            const buttonStyleName = buttonStyleSelector.options[buttonStyleSelector.selectedIndex].text;
            console.log(`✅ Aplicado: ${variantName} + ${buttonStyleName}`);
        }
        
        function applyVariantStyles(contentVariant, buttonStyle, container, userData) {
            // Se o container não existe, cria ele dentro do statusBar
            if (!container) {
                const statusBar = document.getElementById('session-status-bar');
                container = document.createElement('div');
                container.id = 'session-status-container';
                statusBar.appendChild(container);
                debugLog('📦 Container criado dinamicamente');
            }
            
            // Limpa o container e classes antigas
            container.innerHTML = '';
            container.className = '';
            
            // Remove classes antigas da barra e aplica AMBAS classes
            const bar = document.getElementById('session-status-bar');
            bar.className = '';
            bar.classList.add('variant-' + contentVariant);
            bar.classList.add('btn-style-' + buttonStyle);
            
            const statusDiv = document.createElement('div');
            statusDiv.className = 'status-content';
            
            const controlsDiv = document.createElement('div');
            controlsDiv.id = 'session-controls'; // Usa ID para consistência com produção
            controlsDiv.className = 'status-controls';
            
            // HTML base para cada variante (agora usando classes CSS)
            const variants = {
                v1: function() {
                    // Variante 1 - Linha única, outline buttons - USA CLASSES CSS
                    statusDiv.innerHTML = `
                        <div class="v1-status">
                            <div class="status-indicator"></div>
                            <strong>Status:</strong>
                            <span>Conectado (<span class="session-timer">25:13</span>)</span>
                            <span>•</span>
                            👤 <a href="#">${userData.name}</a>
                            <span>•</span>
                            🏅 Placemaker Level ${userData.superuser_level}
                        </div>
                    `;
                    controlsDiv.innerHTML = `
                        <button class="btn refresh">${SVG_ICONS.refresh}Verificar</button>
