                    const wrapper = document.createElement('div');
                    wrapper.className = 'v6-container';
                    
                    const content = document.createElement('div');
                    content.className = 'v6-content';
                    
                    const statusRow = document.createElement('div');
                    statusRow.className = 'v6-status-row';
                    statusRow.innerHTML = `
                        <div class="status-indicator"></div>
                        <strong>Status:</strong>
                        <span>Conectado (<span class="session-timer">25:13</span>)</span>
                    `;
                    
                    const userRow = document.createElement('div');
                    userRow.className = 'v6-user-row';
                    userRow.innerHTML = `<span style="margin-right: 3px;">👤</span> <a href="#" class="v6-user-link">${userData.name}</a> • 🏅 Placemaker Level ${userData.superuser_level}`;
                    
                    content.appendChild(statusRow);
                    content.appendChild(userRow);
                    wrapper.appendChild(content);
                    statusDiv.appendChild(wrapper);
                    
                    controlsDiv.innerHTML = `
                        <button class="btn refresh">${SVG_ICONS.refresh}Verificar</button>
                        <button class="btn info">${SVG_ICONS.info}Sistema</button>
                        <button class="btn debug">${SVG_ICONS.debug}Debug</button>
                        <button class="btn logout">${SVG_ICONS.logout}Logout</button>
                        <button id="session-close-btn" onclick="if(window.sessionStatusBarAPI){window.sessionStatusBarAPI.hide()}">×</button>
                    `;
                },
                v7: function() {
                    // Variante 7 - Grande
                    statusDiv.innerHTML = `
                        <div class="v7-status">
                            <div class="status-indicator"></div>
                            <strong>Status:</strong>
                            <span>Conectado (<span class="session-timer">25:13</span>)</span>
                            <span class="v7-separator">•</span>
                            👤 <a href="#" class="v7-user-link">${userData.name}</a>
                            <span class="v7-separator">•</span>
                            🏅 Placemaker Level ${userData.superuser_level}
                        </div>
                    `;
                    controlsDiv.innerHTML = `
                        <button class="btn refresh">${SVG_ICONS.refresh}Verificar</button>
                        <button class="btn info">${SVG_ICONS.info}Sistema</button>
                        <button class="btn debug">${SVG_ICONS.debug}Debug</button>
                        <button class="btn logout">${SVG_ICONS.logout}Logout</button>
                        <button id="session-close-btn" onclick="if(window.sessionStatusBarAPI){window.sessionStatusBarAPI.hide()}">×</button>
                    `;
                },
                v8: function() {
                    // Variante 8 - Duas linhas com "Usuário:"
                    const wrapper = document.createElement('div');
                    wrapper.className = 'v8-container';
                    
                    const indicator = document.createElement('div');
                    indicator.className = 'status-indicator';
                    
                    const content = document.createElement('div');
                    content.className = 'v8-content';
                    
                    const statusRow = document.createElement('div');
                    statusRow.className = 'v8-status-row';
                    statusRow.innerHTML = `
                        <strong>Status:</strong>
                        <span>Conectado (<span class="session-timer">25:13</span>)</span>
                    `;
                    
                    const userRow = document.createElement('div');
                    userRow.className = 'v8-user-row';
                    userRow.innerHTML = `<strong>Usuário:</strong> <a href="#" class="v8-user-link">${userData.name}</a> • 🏅 Placemaker Level ${userData.superuser_level}`;
                    
                    content.appendChild(statusRow);
                    content.appendChild(userRow);
                    wrapper.appendChild(indicator);
                    wrapper.appendChild(content);
                    statusDiv.appendChild(wrapper);
                    
                    controlsDiv.innerHTML = `
                        <button class="btn refresh">${SVG_ICONS.refresh}Verificar</button>
                        <button class="btn info">${SVG_ICONS.info}Sistema</button>
                        <button class="btn debug">${SVG_ICONS.debug}Debug</button>
                        <button class="btn logout">${SVG_ICONS.logout}Logout</button>
                        <button id="session-close-btn" onclick="if(window.sessionStatusBarAPI){window.sessionStatusBarAPI.hide()}">×</button>
                    `;
                }
            };
            
            // Executa a variante
            if (variants[contentVariant]) {
                variants[contentVariant]();
            }
            
            container.appendChild(statusDiv);
            container.appendChild(controlsDiv);
            
            // Reinicia o timer na barra real
            updateSessionTimer();
        }
        
        // Funções para salvar e carregar variante padrão
        function saveAsDefault() {
            const variantSelector = document.getElementById('variant-selector');
            const buttonStyleSelector = document.getElementById('button-style-selector');
            const contentVariant = variantSelector.value;
            const buttonStyle = buttonStyleSelector.value;
            
            if (!contentVariant) {
                alert('Por favor, selecione e aplique uma variante primeiro!');
                return;
            }
            
            // Salva no localStorage (dual configuration)
            localStorage.setItem('default_content_variant', contentVariant);
            localStorage.setItem('default_button_style', buttonStyle);
            
            // Feedback visual
            const status = document.getElementById('variant-status');
            status.textContent = `✅ Configuração salva: ${contentVariant.toUpperCase()} + ${buttonStyle}`;
            status.style.display = 'block';
            
            setTimeout(() => {
                status.style.display = 'none';
            }, 3000);
            
            console.log(`✅ Padrão salvo: ${contentVariant} + ${buttonStyle}`);
        }
        
        function resetToDefault() {
            localStorage.removeItem('default_content_variant');
            localStorage.removeItem('default_button_style');
            localStorage.removeItem('content_variant');
            localStorage.removeItem('button_style');
            
            // Feedback visual
            const status = document.getElementById('variant-status');
            status.textContent = '🔄 Restaurado para padrão: V8 + Solid';
            status.style.color = '#6c757d';
            status.style.display = 'block';
            
            setTimeout(() => {
                status.style.display = 'none';
                status.style.color = '#28a745';
            }, 3000);
            
            // Reaplica V8 + solid
            const variantSelector = document.getElementById('variant-selector');
            const buttonStyleSelector = document.getElementById('button-style-selector');
            variantSelector.value = 'v8';
            buttonStyleSelector.value = 'solid';
            applyVariant();
            
            console.log('🔄 Restaurado para padrão: V8 + Solid');
        }
        
        // Força mostrar a barra de status para teste
        window.addEventListener('load', function() {
            if (window.sessionStatusBarAPI) {
                window.sessionStatusBarAPI.show();
            }
            
            // Listener para sugerir estilo de botão baseado na variante selecionada
            const variantSelector = document.getElementById('variant-selector');
            const buttonStyleSelector = document.getElementById('button-style-selector');
            
            variantSelector.addEventListener('change', function() {
                const variant = this.value;
                // Sugere estilos específicos para certas variantes (usuário pode mudar depois)
                if (variant === 'v2') {
                    buttonStyleSelector.value = 'outline';
                } else if (variant === 'v3') {
                    buttonStyleSelector.value = 'gradient';
                } else if (variant === 'v5') {
                    buttonStyleSelector.value = 'inverted';
                } else if (variant === 'v7') {
                    buttonStyleSelector.value = 'thick';
                }
                // Outras variantes mantêm seleção atual do usuário
            });
            
            // Aplica configuração salva (dual: content + button style)
            const defaultContentVariant = localStorage.getItem('default_content_variant');
            const defaultButtonStyle = localStorage.getItem('default_button_style');
            const contentVariant = localStorage.getItem('content_variant') || defaultContentVariant || 'v8';
            const buttonStyle = localStorage.getItem('button_style') || defaultButtonStyle || 'solid';
            
            // Reutiliza as variáveis já declaradas acima
            variantSelector.value = contentVariant;
            buttonStyleSelector.value = buttonStyle;
            
            // Auto-aplica a configuração salva
            setTimeout(() => {
                applyVariant();
                console.log(`🎨 Auto-aplicado: ${contentVariant.toUpperCase()} + ${buttonStyle}`);
            }, 500);
        });
    </script>
    
